<?php
require_once dirname(__DIR__).'/app/init.php';require_once dirname(__DIR__).'/app/layout.php';
if(current_user())go('/index.php');$mode=($_GET['mode']??'login')==='register'?'register':'login';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=mb_strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
 if($mode==='register'){$name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190||strlen($password)<10||strlen($password)>200)$error=t('error');else{try{$stmt=db()->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];go('/index.php');}catch(PDOException $e){$error=t('error');}}}
 else{$now=time();if((int)($_SESSION['login_block']??0)>$now)$error=t('error');else{$stmt=db()->prepare("SELECT id,name,email,password_hash,role FROM users WHERE email=? LIMIT 1");$stmt->execute([$email]);$u=$stmt->fetch();if($u&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);unset($_SESSION['login_count'],$_SESSION['login_block']);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];go($u['role']==='admin'?'/admin.php':'/index.php');}$n=(int)($_SESSION['login_count']??0)+1;$_SESSION['login_count']=$n;if($n>=5){$_SESSION['login_block']=$now+600;$_SESSION['login_count']=0;}$error=t('error');}}}
page_header(t($mode));?>
<div class="auth panel stack"><h1><?=h(t($mode))?></h1><?php if($error):?><div class="flash"><?=h($error)?></div><?php endif;?><form method="post" class="stack"><?=csrf_field()?><?php if($mode==='register'):?><label><?=h(t('name'))?><input class="field" name="name" maxlength="120" required></label><?php endif;?><label><?=h(t('email'))?><input class="field" type="email" name="email" maxlength="190" required></label><label><?=h(t('password'))?><input class="field" type="password" name="password" minlength="<?=$mode==='register'?10:1?>" maxlength="200" required></label><button class="btn" type="submit"><?=h(t($mode))?></button></form><a href="/auth.php?mode=<?=$mode==='login'?'register':'login'?>"><?=h(t($mode==='login'?'no_account':'have_account'))?> — <?=h(t($mode==='login'?'register':'login'))?></a></div>
<?php page_footer();?>
